// ---- host logic: examples/api_tours/data_observers/host.cpp ----
// API tour (C++ Wrapper): observable values and bindings, Mutation / Resize / Intersection
// observers, the theme manager and the document router. Same page, checks and case as
// examples/c/ports/kui_api_data_observers.c (and the Go / Rust ports): on start the host calls
// every method once, checks the results and logs one row per check into #tour-log. Resize and
// intersection entries only arrive after rendered frames, so those checks run from a chain of
// timers and #tour-result becomes "PASS n/n" at the end (about 1 s). The panel buttons repeat the
// calls on the visible elements.
//
// Gaps (by design the Wrapper manages object lifetime with RAII; the public C handles are used
// for the reference counting the C port does by hand):
//   kui_observable_retain / _release     -> observable.cHandle() for the extra reference (the Wrapper
//                                           only takes / drops references inside bind / unbind / ~Observable)
//   kui_observer_retain / _release       -> observer->cHandle() (lifetime is RAII: ~ObserverBase releases)
//   kui_observer_observe / _unobserve on a MutationObserver (status check) -> observer->cHandle()
//   kui_theme_manager_release            -> only in ~ThemeManager; the tour destroys a second manager
//   kui_theme_manager_get_variable / _get_theme_name out-of-range status -> themes.cHandle()
// The Wrapper also hides some status codes behind bool / id results (Router::addRoute -> false,
// BindingManager::bind -> 0, ThemeManager::getTheme -> nullptr); those checks compare the equivalent
// Wrapper result. MutationRecord::addedNodeType / removedNodeType / targetNodeType carry the node types.
// A C release_fn has no Wrapper counterpart: the tour counts when the callback's captures are
// destroyed instead (the Wrapper frees them from the C release_fn / its destructor).

#include <cmath>
#include <cstdlib>
#include <cstring>
#include <functional>
#include <memory>
#include <sstream>
#include <vector>

namespace {

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check():  a documented behaviour; a failure makes the tour FAIL.
// known():  a documented behaviour the engine currently gets wrong (reported bug). A failure is
//           logged as "KNOWN BUG" and kept out of the verdict; once it passes it counts as ok.

int g_total = 0;
int g_failed = 0;
int g_known = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    (out << ... << parts);
    return out.str();
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                     : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    if (g_known) text += cat(" (known bugs: ", g_known, ")");
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

// ---- Small readers ---------------------------------------------------------------------------

kui::Element* by_id(const char* id) { return g_doc->getElementById(id); }

bool near(float a, float b, float tolerance) { return std::fabs(a - b) <= tolerance; }

std::string id_of(const kui::Element* element) { return element ? element->id() : std::string(); }

std::string text_of(const char* id) {
    kui::Element* element = by_id(id);
    return element ? element->textContent() : std::string();
}

std::string attr_of(const char* id, const char* name) {
    kui::Element* element = by_id(id);
    return element ? element->getAttribute(name) : std::string();
}

std::string computed(const char* id, const char* property) {
    kui::Element* element = by_id(id);
    return element ? element->computedStylePropertyValue(property) : std::string();
}

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = by_id(id)) element->setTextContent(text);
}

void set_attr(const char* id, const char* name, const char* value) {
    if (kui::Element* element = by_id(id)) element->setAttribute(name, value);
}

void set_style(const char* id, const char* property, const std::string& value) {
    if (kui::Element* element = by_id(id)) element->style()->setProperty(property, value);
}

void set_class(const char* id, const char* name, bool on) {
    kui::Element* element = by_id(id);
    if (element && on) element->addClass(name);
    if (element && !on) element->removeClass(name);
}

void scroll_to(const char* id, float top) {
    if (kui::Element* element = by_id(id)) element->scrollTo(0, top);
}

kui::Rect rect_of(const char* id) {
    kui::Element* element = by_id(id);
    return element ? element->boundingClientRect() : kui::Rect{};
}

// A CSS colour as "#rrggbb" or "rgb(r, g, b)" / "rgba(r, g, b, a)".
bool colour_is(const std::string& value, int r, int g, int b) {
    long got[3] = {-1, -1, -1};
    char* end = nullptr;
    if (value.size() == 7 && value[0] == '#') {
        const long hex = std::strtol(value.c_str() + 1, &end, 16);
        if (*end) return false;
        got[0] = (hex >> 16) & 255;
        got[1] = (hex >> 8) & 255;
        got[2] = hex & 255;
    } else {
        const char* p = std::strchr(value.c_str(), '(');
        if (value.compare(0, 3, "rgb") != 0 || !p) return false;
        for (int index = 0; index < 3; index++) {
            got[index] = std::strtol(p + 1, &end, 10);
            if (end == p + 1) return false;
            p = end;
            while (*p == ' ') p++;
            if (index < 2 && *p != ',') return false;
        }
    }
    return got[0] == r && got[1] == g && got[2] == b;
}

// The current value of an <input> (a page script read: the C ABI has no value getter).
std::string input_value(const char* id) {
    if (!tour_script) return {};
    const kui::ScriptResult result = tour_script->eval(cat("return document:getElementById('", id, "').value"));
    return result.success ? result.value.asString() : std::string();
}

// Stands in for a C release_fn: counts once when the last copy of the callback that holds it
// is destroyed (the Wrapper frees callbacks from the C release_fn or its destructor).
struct ReleaseCounter {
    explicit ReleaseCounter(int* counter) : counter_(counter) {}
    ReleaseCounter(const ReleaseCounter&) = delete;
    ReleaseCounter& operator=(const ReleaseCounter&) = delete;
    ~ReleaseCounter() { ++*counter_; }
    int* counter_;
};

// ---- Observable: values, subscriptions, one- and two-way bindings, flush, refcount ----------

using TextObservable = kui::Observable<std::string>;

int g_sub_calls = 0;
int g_sub_released = 0;

void check_observable() {
    kui::BindingManager& bindings = g_doc->bindingManager();
    std::unique_ptr<TextObservable> obs(new TextObservable("0"));
    std::string value = obs->get();
    check("ob.create_get", obs->cHandle() != nullptr && value == "0", cat("value '", value, "'"));

    {
        std::unique_ptr<kui::ObservableBase> empty(new kui::ObservableBase());
        const std::string text = empty->toString();
        check("ob.create_empty", empty->cHandle() != nullptr && text.empty(), cat("length ", text.size()));
    }

    obs->set("1");
    value = obs->get();
    check("ob.set_get", value == "1", cat("value '", value, "'"));

    // Subscribers run synchronously, and only when the value actually changed.
    const kui::SubscriptionId sub = obs->subscribe([] { g_sub_calls++; });
    obs->set("2");
    check("ob.subscribe", g_sub_calls == 1, cat("calls after one change ", g_sub_calls));
    obs->set("2");
    check("ob.set_unchanged", g_sub_calls == 1, cat("calls after setting the same value ", g_sub_calls));
    obs->unsubscribe(sub);   // the Wrapper ignores the status; the second call reports NOT_FOUND
    obs->set("3");
    check("ob.unsubscribe", sub != 0 && g_sub_calls == 1 &&
                                kui_observable_unsubscribe(obs->cHandle(), sub) == KUI_ERR_NOT_FOUND,
          cat("id ", sub, ", calls ", g_sub_calls));

    // Binding writes the current value right away.
    const kui::BindingId text_binding = bindings.bind(by_id("s-text"), "textContent", obs.get());
    std::string text = text_of("s-text");
    check("ob.bind_text", text_binding != 0 && text == "3", cat("id ", text_binding, ", text '", text, "'"));

    // Later changes are batched until the next frame or an explicit flush.
    obs->set("4");
    text = text_of("s-text");
    check("ob.batched", text == "3", cat("text right after set '", text, "' (want the old '3')"));
    bindings.flush();
    text = text_of("s-text");
    check("ob.flush_bindings", text == "4", cat("text '", text, "'"));

    // Any other property name is an attribute.
    const kui::BindingId attr_binding = bindings.bind(by_id("s-attr"), "data-level", obs.get());
    std::string attr = attr_of("s-attr", "data-level");
    check("ob.bind_attr", attr_binding != 0 && attr == "4", cat("id ", attr_binding, ", data-level '", attr, "'"));

    // "style" is an attribute too: the value is the element's inline declaration.
    std::unique_ptr<TextObservable> style(new TextObservable("background-color: #ff0000"));
    const kui::BindingId style_binding = bindings.bind(by_id("s-style"), "style", style.get());
    const std::string red_css = computed("s-style", "background-color");
    style->set("background-color: #00ff00");
    bindings.flush();
    const std::string green_css = computed("s-style", "background-color");
    check("ob.bind_style", style_binding != 0 && colour_is(red_css, 255, 0, 0) && colour_is(green_css, 0, 255, 0),
          cat("id ", style_binding, ", computed '", red_css, "' then '", green_css, "'"));

    // Two-way: "value" on an <input> (user input writes back; typed by the test case).
    std::unique_ptr<TextObservable> input(new TextObservable("seed"));
    const kui::BindingId input_binding = bindings.bindTwoWay(by_id("s-input"), "value", input.get());
    const std::string seeded = input_value("s-input");
    input->set("next");
    bindings.flush();
    const std::string after = input_value("s-input");
    check("ob.bind_two_way", input_binding != 0 && seeded == "seed" && after == "next",
          cat("id ", input_binding, ", input value '", seeded, "' then '", after, "'"));

    // The C ABI answers INVALID_ARG; the Wrapper returns binding id 0.
    const kui::BindingId invalid = bindings.bind(by_id("s-text"), "", obs.get());
    check("ob.bind_invalid", invalid == 0, cat("empty property -> id ", invalid));

    // Unbinding one binding leaves the others; unbinding it again changes nothing.
    const unsigned count_before = bindings.bindingCount();
    bindings.unbind(text_binding);
    const unsigned count_after = bindings.bindingCount();
    obs->set("5");
    bindings.flush();
    text = text_of("s-text");
    attr = attr_of("s-attr", "data-level");
    bindings.unbind(text_binding);
    check("ob.unbind", count_after + 1 == count_before && bindings.bindingCount() == count_after && text == "4" &&
                           attr == "5",
          cat("bindings ", count_before, " -> ", count_after, ", text '", text, "' (want 4), data-level '", attr,
              "' (want 5)"));

    // Observable::unbindAll removes every binding of this one observable (BindingManager::unbindAll
    // removes every binding it made, of every observable).
    KuiStatus status = KUI_OK;
    try {
        obs->unbindAll();
    } catch (const kui::Error& thrown) {
        status = thrown.status();
    }
    obs->set("6");
    bindings.flush();
    attr = attr_of("s-attr", "data-level");
    bindings.unbind(attr_binding);   // drops the Wrapper's record and its reference (the binding is gone)
    check("ob.unbind_all", status == KUI_OK && attr == "5", cat("status ", status, ", data-level '", attr, "' (want 5)"));

    // Reference counting: one extra retain and its release (C handle, gap), then ~Observable drops
    // the last reference, which releases the subscriptions.
    g_sub_released = 0;
    auto token = std::make_shared<ReleaseCounter>(&g_sub_released);
    obs->subscribe([token] { g_sub_calls++; });
    token.reset();
    const KuiStatus retained = kui_observable_retain(obs->cHandle());
    kui_observable_release(obs->cHandle());
    obs->set("7");
    value = obs->get();
    check("ob.retain_release", retained == KUI_OK && value == "7" && g_sub_released == 0,
          cat("status ", retained, ", value after one release '", value, "', released ", g_sub_released));
    obs.reset();
    check("ob.release_fn", g_sub_released == 1, cat("subscription release ran ", g_sub_released, " times (want 1)"));

    bindings.unbind(style_binding);
    bindings.unbind(input_binding);
}

// ---- MutationObserver: child list, attributes, character data, filter, disconnect --------

struct MutationLog {
    int batches = 0;
    int records = 0;
    kui::MutationRecord::Type type = kui::MutationRecord::Type::ChildList;
    std::string target;
    bool added_element = false;
    std::string added;
    std::string removed;
    std::string attribute;
    std::string old_value;
};

MutationLog g_mlog;
int g_mut_released = 0;

void remember_mutations(const std::vector<kui::MutationRecord>& records) {
    if (records.empty()) return;
    const kui::MutationRecord& last = records.back();
    g_mlog.batches++;
    g_mlog.records += static_cast<int>(records.size());
    g_mlog.type = last.type;
    g_mlog.target = id_of(last.target.get());
    g_mlog.added_element = last.addedNode != nullptr;   // elements only
    g_mlog.added = id_of(last.addedNode.get());
    g_mlog.removed = id_of(last.removedNode.get());
    g_mlog.attribute = last.attributeName;
    g_mlog.old_value = last.oldValue;
}

int type_of(kui::MutationRecord::Type type) { return static_cast<int>(type); }

void check_mutation() {
    using Type = kui::MutationRecord::Type;
    kui::Element* root = by_id("s-mut");
    kui::Element* list = by_id("s-list");
    if (!root || !list) {
        check("mut.page", false, "missing #s-mut / #s-list");
        return;
    }
    g_mut_released = 0;
    auto token = std::make_shared<ReleaseCounter>(&g_mut_released);
    kui::RefPtr<kui::MutationObserver> obs = kui::MutationObserver::create(
        [token](const std::vector<kui::MutationRecord>& records, kui::MutationObserver*) {
            remember_mutations(records);
        });
    token.reset();
    check("mut.create", obs && obs->cHandle() != nullptr, "no observer");

    KuiStatus status = KUI_OK;
    try {
        obs->observe(root, kui::MutationObserverInit{});
    } catch (const kui::Error& error) {
        status = error.status();
    }
    check("mut.observe_needs_kind", status == KUI_ERR_INVALID_ARG,
          cat("no childList / attributes / characterData -> status ", status));

    kui::MutationObserverInit options;
    options.childList = true;
    options.attributes = true;
    options.characterData = true;
    options.subtree = true;
    options.attributeOldValue = true;
    options.characterDataOldValue = true;
    obs->observe(root, options);
    check("mut.observe", g_mlog.batches == 0, cat("batches ", g_mlog.batches));

    // A new child in the subtree: one childList record, delivered synchronously.
    auto item = g_doc->createElement("li");
    item->setTextContent("one");
    item->setId("s-li-1");
    list->appendChild(item);
    check("mut.child_list_add", g_mlog.records == 1 && g_mlog.type == Type::ChildList && g_mlog.target == "s-list" &&
                                    g_mlog.added == "s-li-1" && g_mlog.added_element,
          cat("records ", g_mlog.records, ", type ", type_of(g_mlog.type), ", target '", g_mlog.target, "', added '",
              g_mlog.added, "'"));

    item->remove();
    check("mut.child_list_remove", g_mlog.records == 2 && g_mlog.type == Type::ChildList &&
                                       g_mlog.removed == "s-li-1" && g_mlog.target == "s-list",
          cat("records ", g_mlog.records, ", type ", type_of(g_mlog.type), ", removed '", g_mlog.removed,
              "', target '", g_mlog.target, "'"));

    set_attr("s-mitem", "data-state", "on");
    check("mut.attributes", g_mlog.records == 3 && g_mlog.type == Type::Attributes && g_mlog.target == "s-mitem" &&
                                g_mlog.attribute == "data-state" && g_mlog.old_value == "off",
          cat("type ", type_of(g_mlog.type), ", target '", g_mlog.target, "', name '", g_mlog.attribute, "', old '",
              g_mlog.old_value, "'"));

    // Rewriting the lone text child changes its data in place: a characterData record whose
    // target is the parent element (the Wrapper record has no node type to compare).
    set_text("s-mtext", "world");
    check("mut.character_data", g_mlog.type == Type::CharacterData && g_mlog.target == "s-mtext" &&
                                    g_mlog.old_value == "hello",
          cat("type ", type_of(g_mlog.type), ", target '", g_mlog.target, "', old '", g_mlog.old_value, "'"));

    // Observing again replaces the options: attributes only, filtered to data-state.
    kui::MutationObserverInit filtered_options;
    filtered_options.attributes = true;
    filtered_options.subtree = true;
    filtered_options.attributeFilter = {"data-state"};
    obs->observe(root, filtered_options);
    int before = g_mlog.records;
    set_attr("s-mitem", "title", "ignored");
    set_text("s-mtext", "again");
    const bool filtered = g_mlog.records == before;
    set_attr("s-mitem", "data-state", "off");
    check("mut.attribute_filter", filtered && g_mlog.records == before + 1 && g_mlog.attribute == "data-state" &&
                                      g_mlog.old_value.empty(),
          cat("filtered ", filtered, ", records ", before, " -> ", g_mlog.records, ", name '", g_mlog.attribute,
              "', old '", g_mlog.old_value, "' (not requested)"));

    // The generic observe / unobserve are not for mutation observers (no Wrapper method: C handle).
    status = kui_observer_observe(obs->cHandle(), root->cHandle());
    const KuiStatus unobserve = kui_observer_unobserve(obs->cHandle(), root->cHandle());
    check("mut.generic_observe", status == KUI_ERR_INVALID_ARG && unobserve == KUI_ERR_NOT_SUPPORTED,
          cat("observer_observe ", status, " (want INVALID_ARG), observer_unobserve ", unobserve,
              " (want NOT_SUPPORTED)"));

    // One retain, one release (gap: C handle): still observing.
    status = kui_observer_retain(obs->cHandle());
    kui_observer_release(obs->cHandle());
    before = g_mlog.records;
    set_attr("s-mitem", "data-state", "on");
    check("mut.retain_release", status == KUI_OK && g_mlog.records == before + 1 && g_mut_released == 0,
          cat("status ", status, ", records ", before, " -> ", g_mlog.records, ", released ", g_mut_released));

    obs->disconnect();
    before = g_mlog.records;
    set_attr("s-mitem", "data-state", "off");
    check("mut.disconnect", g_mlog.records == before, cat("records ", before, " -> ", g_mlog.records));

    obs.reset();   // ~ObserverBase -> kui_observer_release; the callback goes with the observer
    check("mut.release_fn", g_mut_released == 1, cat("callback release ran ", g_mut_released, " times (want 1)"));
}

// ---- Theme manager: built-ins, register / replace, apply, enumerate ----------------------

kui::ThemeManager* g_themes = nullptr;   // process lifetime

bool has_theme(const char* name) {
    for (const std::string& theme : g_themes->themeNames()) {
        if (theme == name) return true;
    }
    return false;
}

// The value of one variable of a theme ("" when the theme or the variable is missing).
std::string theme_variable(const char* theme, const char* name) {
    const kui::Theme* found = g_themes->getTheme(theme);
    if (!found) return {};
    const auto it = found->variables.find(name);
    return it == found->variables.end() ? std::string() : it->second;
}

std::string html_custom_property(const char* name) {
    kui::Element* html = g_doc->documentElement();
    return html ? html->style()->getPropertyValue(name) : std::string();
}

kui::Theme make_theme(const char* name, const char* bg, const char* fg, const char* accent) {
    kui::Theme theme;
    theme.name = name;
    theme.variables = {{"--tour-bg", bg}, {"--tour-fg", fg}, {"--tour-accent", accent}};
    return theme;
}

void check_theme() {
    g_themes = new kui::ThemeManager();
    std::size_t count = g_themes->themeNames().size();
    check("th.builtin", count == 2 && has_theme("light") && has_theme("dark"),
          cat("count ", count, ", light ", has_theme("light"), ", dark ", has_theme("dark")));

    const kui::Theme* dark = g_themes->getTheme("dark");
    std::size_t vars = dark ? dark->variables.size() : 0;
    bool all_custom = true;
    if (dark) {
        for (const auto& entry : dark->variables) {
            if (entry.first.compare(0, 2, "--") != 0 || entry.first.find('\0') != std::string::npos) all_custom = false;
        }
    }
    check("th.builtin_variables", vars > 0 && all_custom,
          cat("dark has ", vars, " variables, all custom properties ", all_custom));

    std::string active = g_themes->activeTheme();
    check("th.active_empty", active.empty(), cat("active before any apply '", active, "'"));

    g_themes->registerTheme("tour-light", make_theme("tour-light", "#f0fdf4", "#14532d", "#22c55e"));
    g_themes->registerTheme("tour-dark", make_theme("tour-dark", "#0f172a", "#e2e8f0", "#38bdf8"));
    count = g_themes->themeNames().size();
    const kui::Theme* light = g_themes->getTheme("tour-light");
    vars = light ? light->variables.size() : 0;
    check("th.register", count == 4 && has_theme("tour-dark") && vars == 3,
          cat("count ", count, ", tour-light variables ", vars));

    std::string value = theme_variable("tour-light", "--tour-fg");
    check("th.get_variable", value == "#14532d", cat("tour-light --tour-fg '", value, "'"));

    // Registering an existing name replaces it.
    g_themes->registerTheme("tour-dark", make_theme("tour-dark", "#0f172a", "#e2e8f0", "#f59e0b"));
    count = g_themes->themeNames().size();
    value = theme_variable("tour-dark", "--tour-accent");
    check("th.register_replace", count == 4 && value == "#f59e0b", cat("count ", count, ", --tour-accent '", value, "'"));

    // getTheme() answers nullptr for an unknown theme; the out-of-range statuses have no Wrapper
    // method (C handle).
    const bool unknown = g_themes->getTheme("nope") == nullptr;
    char key[64];
    char text[64];
    std::size_t name_len = 0;
    std::size_t value_len = 0;
    const KuiStatus range = kui_theme_manager_get_variable(g_themes->cHandle(), "tour-dark", 0, 3, key, sizeof key,
                                                           &name_len, text, sizeof text, &value_len);
    const KuiStatus name = kui_theme_manager_get_theme_name(g_themes->cHandle(), 4, key, sizeof key, &name_len);
    check("th.not_found", unknown && range == KUI_ERR_NOT_FOUND && name == KUI_ERR_NOT_FOUND,
          cat("unknown theme found ", !unknown, ", variable index 3 -> ", range, ", theme index 4 -> ", name));

    // Applying sets the variables inline on <html>; the card picks them up through var().
    g_themes->apply("tour-dark", g_doc);
    active = g_themes->activeTheme();
    value = html_custom_property("--tour-bg");
    std::string css = computed("theme-card", "background-color");
    check("th.apply", active == "tour-dark" && value == "#0f172a",
          cat("active '", active, "', <html> --tour-bg '", value, "'"));
    check("th.apply_computed", colour_is(css, 0x0f, 0x17, 0x2a), cat("card background-color '", css, "'"));

    // An unknown theme is ignored (C ABI: NOT_FOUND; the Wrapper does not throw).
    g_themes->apply("nope", g_doc);
    active = g_themes->activeTheme();
    check("th.apply_unknown", active == "tour-dark", cat("active '", active, "'"));

    g_themes->apply("tour-light", g_doc);
    css = computed("theme-card", "background-color");
    check("th.switch", colour_is(css, 0xf0, 0xfd, 0xf4), cat("card background-color after tour-light '", css, "'"));

    // A second manager: created, used and destroyed (~ThemeManager -> kui_theme_manager_release).
    bool created = false;
    {
        kui::ThemeManager other;
        created = other.cHandle() != nullptr && other.themeNames().size() == 2;
    }
    check("th.release", created, "a second manager did not come up with the two built-ins");
}

// ---- Router: routes, views, navigation, history, params, guards, callbacks ---------------

enum { VIEW_HOME, VIEW_USER, VIEW_ABOUT, VIEW_ADMIN };
int g_nav_calls = 0;
int g_route_released = 0;
std::string g_nav_path;
std::string g_guard_seen;
bool g_block_leave_about = false;
bool g_admin_locked = true;
kui::u32 g_admin_guard = 0;
kui::u32 g_nav_callback = 0;

// Builds the view for the current route. `token` (the "/" route only) counts when KUI lets go
// of the route's factory.
kui::RouteDefinition::ViewFactory view_factory(int kind, std::shared_ptr<ReleaseCounter> token = nullptr) {
    return [kind, token](kui::Document* doc, const kui::RouteParams& params) -> kui::RefPtr<kui::Node> {
        static const char* const ids[4] = {"view-home", "view-user", "view-about", "view-admin"};
        static const char* const titles[4] = {"Home", "User", "About", "Admin area"};
        (void)token;
        auto view = doc->createElement("div");
        view->setId(ids[kind]);
        view->setAttribute("class", "view");
        if (kind == VIEW_USER) {
            const auto id = params.find("id");
            view->setTextContent(cat("User ", id == params.end() ? std::string() : id->second));
        } else {
            view->setTextContent(titles[kind]);
        }
        return view;
    };
}

void on_navigated(const kui::RouteContext& route) {
    g_nav_calls++;
    g_nav_path = route.path;
    set_text("route-nav", cat("navigated: ", route.path, " (pattern ", route.pattern, ")"));
}

std::string current_path() { return g_doc->router().currentPath(); }

// A ":name" parameter of the current route: OK with its value, NOT_FOUND when the route has none.
KuiStatus route_param(const char* name, std::string* out) {
    const auto value = g_doc->router().param(name);
    if (out) *out = value ? *value : std::string();
    return value ? KUI_OK : KUI_ERR_NOT_FOUND;
}

// The id of the view element the router put into #route-view ("" when empty).
std::string view_id() {
    kui::Element* view = by_id("route-view");
    return view ? id_of(view->firstElementChild()) : std::string();
}

unsigned view_children() {
    kui::Element* view = by_id("route-view");
    return view ? view->childElementCount() : 99u;
}

bool add_routes(kui::Router& router) {
    bool ok = router.addRoute("/", view_factory(VIEW_HOME, std::make_shared<ReleaseCounter>(&g_route_released)), "home");
    ok = router.addRoute("/user/:id", view_factory(VIEW_USER), "user") && ok;
    ok = router.addRoute("/about", view_factory(VIEW_ABOUT), "about") && ok;
    ok = router.addRoute("/admin", view_factory(VIEW_ADMIN), "admin") && ok;
    return ok;
}

void check_router() {
    kui::Router& router = g_doc->router();
    kui::Element* view = by_id("route-view");
    if (!view) {
        check("rt.page", false, "missing #route-view");
        return;
    }
    int index = router.historyIndex();
    int size = router.historySize();
    check("rt.history_initial", index == -1 && size == 0, cat("index ", index, ", size ", size, " (want -1, 0)"));

    const bool added = add_routes(router);
    unsigned count = router.routeCount();
    bool has = router.hasRoute("/user/:id");
    check("rt.add_route", added && count == 4 && has, cat("added ", added, ", count ", count, ", has /user/:id ", has));
    const bool duplicate = router.addRoute("/about", view_factory(VIEW_ABOUT), "again");
    has = router.hasRoute("/nope");
    check("rt.add_route_duplicate", !duplicate && !has, cat("duplicate added ", duplicate, ", has /nope ", has));

    router.addRoute("/tmp", view_factory(VIEW_HOME), "tmp");
    const bool removed = router.removeRoute("/tmp");
    count = router.routeCount();
    check("rt.remove_route", removed && count == 4 && !router.removeRoute("/tmp"),
          cat("removed ", removed, ", count ", count));

    router.registerView(view);
    g_nav_callback = router.onAfterNavigate(on_navigated);
    check("rt.register_view", g_nav_callback != 0 && view_children() == 0, cat("children ", view_children()));

    bool navigated = router.push("/");
    std::string path = current_path();
    std::string id = view_id();
    check("rt.push", navigated && path == "/" && router.currentPath() == "/" && id == "view-home",
          cat("navigated ", navigated, ", path '", path, "', view '", id, "'"));
    check("rt.navigated_callback", g_nav_calls == 1 && g_nav_path == "/",
          cat("calls ", g_nav_calls, ", last path '", g_nav_path, "'"));

    navigated = router.push("/user/42?tab=2");
    std::string param;
    route_param("id", &param);
    id = view_id();
    const std::string user_text = text_of("view-user");
    check("rt.push_param", navigated && param == "42" && id == "view-user" && user_text == "User 42",
          cat("navigated ", navigated, ", param id '", param, "', view '", id, "' '", user_text, "'"));
    kui::RouteContext route = router.currentRoute();
    const auto tab = route.queryParams.find("tab");
    const std::string tab_value = tab == route.queryParams.end() ? std::string() : tab->second;
    check("rt.get_current", route.path == "/user/42?tab=2" && route.pattern == "/user/:id" && route.query == "tab=2" &&
                                tab_value == "2" && route.params.size() == 1,
          cat("path '", route.path, "', pattern '", route.pattern, "', query '", route.query, "', tab '", tab_value,
              "', params ", route.params.size()));
    check("rt.get_param_missing", route_param("nope", nullptr) == KUI_ERR_NOT_FOUND,
          "get_param(nope) should be NOT_FOUND");
    index = router.historyIndex();
    size = router.historySize();
    check("rt.history", index == 1 && size == 2, cat("index ", index, ", size ", size, " (want 1, 2)"));

    navigated = router.back();
    path = current_path();
    index = router.historyIndex();
    size = router.historySize();
    check("rt.go_back", navigated && path == "/" && index == 0 && size == 2,
          cat("navigated ", navigated, ", path '", path, "', index ", index, ", size ", size));
    navigated = router.forward();
    path = current_path();
    check("rt.go_forward", navigated && path == "/user/42?tab=2", cat("navigated ", navigated, ", path '", path, "'"));
    navigated = router.go(5);
    check("rt.go_out_of_range", !navigated, cat("go(5) navigated ", navigated));

    navigated = router.replace("/about");
    path = current_path();
    index = router.historyIndex();
    size = router.historySize();
    id = view_id();
    check("rt.replace", navigated && path == "/about" && index == 1 && size == 2 && id == "view-about",
          cat("navigated ", navigated, ", path '", path, "', index ", index, ", size ", size, ", view '", id, "'"));

    // Guards: before-enter refuses /admin; before-leave refuses /about -> /.
    const kui::u32 enter = router.addBeforeEnter([](const kui::RouteContext& from, const kui::RouteContext& to) {
        g_guard_seen = cat(from.path, " -> ", to.path);
        return to.path != "/admin";
    });
    int calls = g_nav_calls;
    navigated = router.push("/admin");
    path = current_path();
    check("rt.guard_enter_blocks", !navigated && path == "/about" && g_nav_calls == calls &&
                                       g_guard_seen == "/about -> /admin",
          cat("navigated ", navigated, ", path '", path, "', callbacks ", calls, " -> ", g_nav_calls, ", guard saw '",
              g_guard_seen, "'"));

    const kui::u32 leave = router.addBeforeLeave([](const kui::RouteContext& from, const kui::RouteContext& to) {
        return !(g_block_leave_about && from.path == "/about" && to.path == "/");
    });
    g_block_leave_about = true;
    navigated = router.push("/");
    path = current_path();
    check("rt.guard_leave_blocks", !navigated && path == "/about", cat("navigated ", navigated, ", path '", path, "'"));
    router.removeGuard(leave);
    navigated = router.push("/");
    path = current_path();
    check("rt.remove_guard", navigated && path == "/", cat("navigated ", navigated, ", path '", path, "'"));
    router.removeGuard(enter);
    navigated = router.push("/admin");
    id = view_id();
    check("rt.guard_removed_allows", navigated && id == "view-admin", cat("navigated ", navigated, ", view '", id, "'"));

    // A path no route matches still navigates and empties the view.
    navigated = router.push("/missing");
    route = router.currentRoute();
    check("rt.unmatched", navigated && route.pattern.empty() && view_children() == 0,
          cat("navigated ", navigated, ", pattern '", route.pattern, "', children ", view_children()));

    calls = g_nav_calls;
    router.removeAfterNavigate(g_nav_callback);
    router.push("/about");
    check("rt.remove_navigated_callback", g_nav_calls == calls, cat("callbacks ", calls, " -> ", g_nav_calls));

    // Router::unregisterView returns whether the view was registered: true the first time, false the second.
    const bool first = router.unregisterView(view);
    router.push("/");
    const unsigned children = view_children();
    check("rt.unregister_view", first && children == 1 && !router.unregisterView(view),
          cat("children after navigating unregistered ", children, " (want the old 1)"));
    // Registering fills the view right away with the current route.
    router.registerView(view);
    id = view_id();
    check("rt.register_fills", id == "view-home", cat("view after register '", id, "'"));

    router.clearRoutes();
    count = router.routeCount();
    has = router.hasRoute("/");
    check("rt.clear_routes", count == 0 && !has, cat("count ", count, ", has / ", has));

    // Set up again for the panel: routes, the /admin lock and the navigated callback.
    add_routes(router);
    g_admin_guard = router.addBeforeEnter([](const kui::RouteContext&, const kui::RouteContext& to) {
        return !(g_admin_locked && to.path == "/admin");
    });
    g_nav_callback = router.onAfterNavigate(on_navigated);
    // The cleared "/" route stays referenced while it is the current route's view factory; the
    // next navigation lets go of it and its release runs (once).
    const int released = g_route_released;
    router.push("/");
    check("rt.route_release_fn", released == 0 && g_route_released == 1,
          cat("release ran ", released, " times before / ", g_route_released, " after the next navigation (want 0 / 1)"));
}

// ---- Resize & intersection observers: entries after rendered frames (timer chain) --------

struct SizeLog {
    int reports = 0;
    float content_w = 0, content_h = 0, border_w = 0, border_h = 0, content_x = 0, content_y = 0;
};

struct SeenLog {
    int reports = 0;
    bool intersecting = false;
    float ratio = 0;
    kui::Rect root;
};

// Process-lifetime observers (never destroyed, like the C port's handles).
kui::RefPtr<kui::ResizeObserver>* g_resize = nullptr;
kui::RefPtr<kui::IntersectionObserver>* g_inter = nullptr;
kui::RefPtr<kui::IntersectionObserver> g_viewport;   // released in phase 3
SizeLog g_rs_box, g_rs_fluid;
SeenLog g_io_a, g_io_b, g_io_panel;
int g_rs_width = 160;

std::string fixed(float value, int digits) {
    char buffer[32];
    std::snprintf(buffer, sizeof buffer, "%.*f", digits, value);
    return buffer;
}

void show_resize() {
    set_text("rs-out", cat("box ", fixed(g_rs_box.content_w, 0), "x", fixed(g_rs_box.content_h, 0), " (border ",
                           fixed(g_rs_box.border_w, 0), "x", fixed(g_rs_box.border_h, 0), ") | fluid ",
                           fixed(g_rs_fluid.content_w, 0)));
}

void on_resize(const std::vector<kui::ResizeObserverEntry>& entries) {
    for (const kui::ResizeObserverEntry& entry : entries) {
        const std::string id = id_of(entry.target);
        SizeLog* log = id == "rs-box" ? &g_rs_box : id == "rs-fluid" ? &g_rs_fluid : nullptr;
        if (!log) continue;
        log->reports++;
        log->content_w = entry.contentBoxSize.inlineSize;
        log->content_h = entry.contentBoxSize.blockSize;
        log->border_w = entry.borderBoxSize.inlineSize;
        log->border_h = entry.borderBoxSize.blockSize;
        log->content_x = entry.contentRectX;
        log->content_y = entry.contentRectY;
    }
    show_resize();
}

void show_intersection() {
    set_text("io-out", cat("A ", g_io_a.intersecting ? "in" : "out", " ", fixed(g_io_a.ratio, 2), " | B ",
                           g_io_b.intersecting ? "in" : "out", " ", fixed(g_io_b.ratio, 2)));
}

void remember_seen(SeenLog* log, const kui::IntersectionObserverEntry& entry) {
    log->reports++;
    log->intersecting = entry.isIntersecting;
    log->ratio = entry.intersectionRatio;
    log->root = entry.rootBounds;
}

void on_intersection(const std::vector<kui::IntersectionObserverEntry>& entries) {
    for (const kui::IntersectionObserverEntry& entry : entries) {
        const std::string id = id_of(entry.target);
        if (id == "io-a") remember_seen(&g_io_a, entry);
        if (id == "io-b") remember_seen(&g_io_b, entry);
    }
    show_intersection();
}

void on_viewport_intersection(const std::vector<kui::IntersectionObserverEntry>& entries) {
    for (const kui::IntersectionObserverEntry& entry : entries) remember_seen(&g_io_panel, entry);
}

int g_fluid_reports_frozen = 0;
float g_fluid_before = 0;

// The next step of the chain in `ms`; a timer that cannot be set ends the tour.
void after(void (*step)(), unsigned ms) {
    try {
        kui::Platform::setTimeout([step] { run_group("frames", step); }, ms);
    } catch (const kui::Error& error) {
        check("frames.timer", false, cat("Platform::setTimeout failed: ", error.what()));
        finish();
    }
}

void frames_phase3() {
    check("rs.unobserve", g_rs_fluid.reports == g_fluid_reports_frozen,
          cat("unobserved fluid reports ", g_fluid_reports_frozen, " -> ", g_rs_fluid.reports));
    // The resize observer was retained once and released once in phase 1: still delivering.
    check("rs.retain_release", near(g_rs_box.content_w, 160, 0.5f),
          cat("box content width after the reset ", g_rs_box.content_w, " (want 160)"));
    check("io.scroll_back", g_io_a.intersecting && near(g_io_a.ratio, 1, 0.01f) && !g_io_b.intersecting,
          cat("A ", g_io_a.intersecting, " ", g_io_a.ratio, ", B ", g_io_b.intersecting));
    g_viewport.reset();
    (*g_resize)->observe(by_id("rs-fluid"));   // back on for the panel buttons
    finish();
}

void frames_phase2() {
    const kui::Rect fluid = rect_of("rs-fluid");
    check("rs.resize_box", g_rs_box.reports >= 2 && near(g_rs_box.content_w, 200, 0.5f) &&
                               near(g_rs_box.border_w, 220, 0.5f),
          cat("reports ", g_rs_box.reports, ", content ", g_rs_box.content_w, ", border ", g_rs_box.border_w,
              " (want 200, 220)"));
    check("rs.resize_layout", g_rs_fluid.reports >= 2 && near(g_rs_fluid.content_w, fluid.width, 0.6f) &&
                                  g_rs_fluid.content_w < g_fluid_before - 10,
          cat("reports ", g_rs_fluid.reports, ", content ", g_rs_fluid.content_w, " (laid out ", fluid.width,
              ", before ", g_fluid_before, ")"));
    check("io.scroll_in", g_io_b.intersecting && near(g_io_b.ratio, 1, 0.01f),
          cat("B intersecting ", g_io_b.intersecting, ", ratio ", g_io_b.ratio));
    check("io.scroll_out", !g_io_a.intersecting && near(g_io_a.ratio, 0, 0.01f),
          cat("A intersecting ", g_io_a.intersecting, ", ratio ", g_io_a.ratio));

    // Stop watching the fluid box, then change everything back.
    (*g_resize)->unobserve(by_id("rs-fluid"));
    g_fluid_reports_frozen = g_rs_fluid.reports;
    set_class("rs-stage", "narrow", false);
    set_style("rs-box", "width", "160px");
    scroll_to("io-scroller", 0);
    after(frames_phase3, 350);
}

void frames_phase1() {
    const kui::Rect stage = rect_of("rs-stage");
    kui::Element* scroller = by_id("io-scroller");
    const float client_w = scroller ? scroller->clientWidth() : 0.0f;
    const float client_h = scroller ? scroller->clientHeight() : 0.0f;

    // content-box 160x40, padding 8, border 2: border box 180x60, content at 10,10.
    check("rs.first_report", g_rs_box.reports >= 1 && near(g_rs_box.content_w, 160, 0.5f) &&
                                 near(g_rs_box.content_h, 40, 0.5f) && near(g_rs_box.border_w, 180, 0.5f) &&
                                 near(g_rs_box.border_h, 60, 0.5f),
          cat("reports ", g_rs_box.reports, ", content ", g_rs_box.content_w, "x", g_rs_box.content_h, ", border ",
              g_rs_box.border_w, "x", g_rs_box.border_h));
    // kui_c.h: content_x / content_y are the content box offset inside the border box.
    known("rs.content_offset", near(g_rs_box.content_x, 10, 0.5f) && near(g_rs_box.content_y, 10, 0.5f),
          "content_x / content_y give the padding offset (contentRect.x), not the documented offset "
          "inside the border box (padding + border)",
          cat("offset ", fixed(g_rs_box.content_x, 1), ",", fixed(g_rs_box.content_y, 1), " (want 10,10)"));
    // 50% of the stage's content box (border 1 + padding 4 on each side).
    check("rs.percentage", g_rs_fluid.reports >= 1 && near(g_rs_fluid.content_w, (stage.width - 10) / 2, 0.6f),
          cat("reports ", g_rs_fluid.reports, ", content ", g_rs_fluid.content_w, ", stage ", stage.width));
    check("io.first_report", g_io_a.reports >= 1 && g_io_b.reports >= 1,
          cat("reports A ", g_io_a.reports, ", B ", g_io_b.reports));
    check("io.visible", g_io_a.intersecting && near(g_io_a.ratio, 1, 0.01f),
          cat("A intersecting ", g_io_a.intersecting, ", ratio ", g_io_a.ratio));
    check("io.hidden", !g_io_b.intersecting && near(g_io_b.ratio, 0, 0.01f),
          cat("B intersecting ", g_io_b.intersecting, ", ratio ", g_io_b.ratio));
    // W3C IntersectionObserver (which the native observer follows): an element root that clips
    // its content intersects through its padding area, i.e. the client rect.
    known("io.root_bounds", near(g_io_a.root.height, client_h, 1.0f) && near(g_io_a.root.width, client_w, 1.0f),
          "root_bounds is the root's border box (border and scrollbar included), not its padding area",
          cat("root ", fixed(g_io_a.root.width, 1), "x", fixed(g_io_a.root.height, 1), ", scroller client ",
              fixed(client_w, 1), "x", fixed(client_h, 1)));
    check("io.viewport_root", g_io_panel.reports >= 1 && g_io_panel.intersecting,
          cat("panel against the viewport: reports ", g_io_panel.reports, ", intersecting ", g_io_panel.intersecting));

    kui_observer_release((*g_resize)->cHandle());   // drops the extra reference taken in start_frame_checks()
    g_fluid_before = g_rs_fluid.content_w;
    set_style("rs-box", "width", "200px");
    set_class("rs-stage", "narrow", true);
    scroll_to("io-scroller", 10000);
    after(frames_phase2, 350);
}

void start_frame_checks() {
    kui::IntersectionObserverInit options;
    options.root = by_id("io-scroller");
    options.thresholds = {0.0f, 0.5f, 1.0f};
    std::string failure;
    try {
        g_resize = new kui::RefPtr<kui::ResizeObserver>(
            kui::ResizeObserver::create([](const std::vector<kui::ResizeObserverEntry>& entries, kui::ResizeObserver*) {
                on_resize(entries);
            }));
        g_inter = new kui::RefPtr<kui::IntersectionObserver>(kui::IntersectionObserver::create(
            [](const std::vector<kui::IntersectionObserverEntry>& entries, kui::IntersectionObserver*) {
                on_intersection(entries);
            },
            options));
        // No root: against the viewport.
        g_viewport = kui::IntersectionObserver::create(
            [](const std::vector<kui::IntersectionObserverEntry>& entries, kui::IntersectionObserver*) {
                on_viewport_intersection(entries);
            });
    } catch (const kui::Error& error) {
        failure = error.what();
    }
    check("frames.create", failure.empty(), failure);
    if (!failure.empty()) {
        finish();
        return;
    }
    // Gap: kui_observer_retain has no Wrapper method -> the observer's C handle.
    const KuiStatus retain = kui_observer_retain((*g_resize)->cHandle());
    check("frames.retain", retain == KUI_OK, cat("observer_retain ", retain));
    (*g_resize)->observe(by_id("rs-box"));
    (*g_resize)->observe(by_id("rs-fluid"));
    (*g_inter)->observe(by_id("io-a"));
    (*g_inter)->observe(by_id("io-b"));
    g_viewport->observe(by_id("p-io"));
    after(frames_phase1, 350);
}

// ---- Panel: observable & bindings ----------------------------------------------------------

// Process-lifetime observables (the document's BindingManager drops its references at exit).
kui::Observable<int>* g_count = nullptr;
TextObservable* g_level = nullptr;
TextObservable* g_badge_style = nullptr;
TextObservable* g_name = nullptr;
kui::BindingId g_text_binding = 0;

void show_observable() {
    set_text("ob-out", cat("count=", g_count->toString(), " text=", text_of("ob-text"), " level=", g_level->get(),
                           " bound=", g_text_binding ? "yes" : "no"));
}

void on_name_changed() { set_text("ob-echo", cat("echo: ", g_name->get())); }

void setup_observable_panel() {
    kui::BindingManager& bindings = g_doc->bindingManager();
    g_count = new kui::Observable<int>(0);
    g_level = new TextObservable("cool");
    g_badge_style = new TextObservable("background-color: #dbeafe");
    g_name = new TextObservable("KUI");
    g_text_binding = bindings.bind(by_id("ob-text"), "textContent", g_count);
    bindings.bind(by_id("ob-badge"), "data-level", g_level);
    bindings.bind(by_id("ob-badge"), "style", g_badge_style);
    bindings.bindTwoWay(by_id("ob-input"), "value", g_name);
    g_name->subscribe(on_name_changed);
    on_name_changed();
    show_observable();
}

void on_ob_inc() {
    g_count->modify([](int& value) { value++; });
    g_doc->bindingManager().flush();
    show_observable();
}

void on_ob_color() {
    const bool hot = g_level->get() != "hot";
    g_level->set(hot ? "hot" : "cool");
    g_badge_style->set(hot ? "background-color: #fee2e2" : "background-color: #dbeafe");
    g_doc->bindingManager().flush();
    show_observable();
}

void on_ob_unbind() {
    if (g_text_binding) g_doc->bindingManager().unbind(g_text_binding);
    g_text_binding = 0;
    show_observable();
}

void on_ob_rebind() {
    if (!g_text_binding) g_text_binding = g_doc->bindingManager().bind(by_id("ob-text"), "textContent", g_count);
    show_observable();
}

// ---- Panel: MutationObserver ----------------------------------------------------------------

kui::RefPtr<kui::MutationObserver>* g_mut_panel = nullptr;   // process lifetime
int g_mut_total = 0;
int g_mut_next = 1;

void on_panel_mutations(const std::vector<kui::MutationRecord>& records) {
    static const char* const types[3] = {"childList", "attributes", "characterData"};
    if (records.empty()) return;
    const kui::MutationRecord& last = records.back();
    g_mut_total += static_cast<int>(records.size());
    std::string out = cat("records=", g_mut_total, " | ", types[type_of(last.type)], " #", id_of(last.target.get()));
    const std::string added = id_of(last.addedNode.get());
    const std::string removed = id_of(last.removedNode.get());
    if (!added.empty()) out += " +#" + added;
    if (!removed.empty()) out += " -#" + removed;
    if (last.type == kui::MutationRecord::Type::Attributes) out += " " + last.attributeName;
    if (last.type != kui::MutationRecord::Type::ChildList) out += " old=" + last.oldValue;
    set_text("mut-out", out);
}

void observe_mut_panel() {
    kui::MutationObserverInit options;
    options.childList = true;
    options.attributes = true;
    options.characterData = true;
    options.subtree = true;
    options.attributeOldValue = true;
    options.characterDataOldValue = true;
    if (kui::Element* box = by_id("mut-box")) (*g_mut_panel)->observe(box, options);
}

void on_mut_add() {
    kui::Element* list = by_id("mut-list");
    if (!list) return;
    auto item = g_doc->createElement("li");
    item->setTextContent(cat("item ", g_mut_next));
    item->setId(cat("mut-li-", g_mut_next));
    g_mut_next++;
    list->appendChild(item);
}

void on_mut_remove() {
    kui::Element* list = by_id("mut-list");
    kui::Element* last = list ? list->lastElementChild() : nullptr;
    if (last) list->removeChild(last);
}

void on_mut_attr() { set_attr("mut-item", "data-state", attr_of("mut-item", "data-state") == "on" ? "off" : "on"); }
void on_mut_text() { set_text("mut-text", text_of("mut-text") == "hello" ? "world" : "hello"); }

void on_mut_stop() {
    (*g_mut_panel)->disconnect();
    set_text("mut-out", cat("disconnected (records=", g_mut_total, ")"));
}

void on_mut_start() {
    observe_mut_panel();
    set_text("mut-out", cat("observing (records=", g_mut_total, ")"));
}

// ---- Panel: resize & intersection buttons --------------------------------------------------

void apply_rs_width() { set_style("rs-box", "width", cat(g_rs_width, "px")); }

void on_rs_grow() {
    g_rs_width += 40;
    apply_rs_width();
}

void on_rs_reset() {
    g_rs_width = 160;
    apply_rs_width();
    set_class("rs-stage", "narrow", false);
}

void on_rs_stage() {
    kui::Element* stage = by_id("rs-stage");
    if (stage) set_class("rs-stage", "narrow", !stage->hasClass("narrow"));
}

void on_io_bottom() { scroll_to("io-scroller", 10000); }
void on_io_top() { scroll_to("io-scroller", 0); }

// ---- Panel: themes -------------------------------------------------------------------------

void show_theme() {
    set_text("theme-out", cat("active=", g_themes->activeTheme(), " | --tour-bg=", html_custom_property("--tour-bg")));
}

void on_th_light() { g_themes->apply("tour-light", g_doc); show_theme(); }
void on_th_dark() { g_themes->apply("tour-dark", g_doc); show_theme(); }

void on_th_list() {
    const std::vector<std::string> names = g_themes->themeNames();
    std::string out = cat(names.size(), " themes:");
    for (const std::string& name : names) {
        const kui::Theme* theme = g_themes->getTheme(name);
        out += cat(" ", name, "(", theme ? theme->variables.size() : 0, ")");
    }
    set_text("theme-out", out);
}

// ---- Panel: router -------------------------------------------------------------------------

void show_route(const std::string& note) {
    kui::Router& router = g_doc->router();
    const kui::RouteContext route = router.currentRoute();
    const auto id = route.params.find("id");
    set_text("route-out", cat(note, "path=", route.path, " pattern=", route.pattern, " | ", router.historyIndex(), "/",
                              router.historySize(), " | id=", id == route.params.end() ? std::string("-") : id->second,
                              " | locked=", g_admin_locked ? "yes" : "no"));
}

void navigate(const char* path, bool replace) {
    kui::Router& router = g_doc->router();
    const bool navigated = replace ? router.replace(path) : router.push(path);
    show_route(navigated ? std::string() : cat("blocked ", path, " | "));
}

void on_rt_home() { navigate("/", false); }
void on_rt_user() { navigate("/user/7", false); }
void on_rt_about() { navigate("/about", true); }
void on_rt_admin() { navigate("/admin", false); }

void on_rt_lock() {
    g_admin_locked = !g_admin_locked;
    show_route("");
}

void on_rt_back() { show_route(g_doc->router().back() ? "" : "no back | "); }
void on_rt_fwd() { show_route(g_doc->router().forward() ? "" : "no forward | "); }

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = by_id(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler, id](kui::Event&) {
        try {
            handler();
        } catch (const std::exception& error) {
            std::fprintf(stderr, "%s: %s\n", id, error.what());
        }
    });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;

    run_group("ob", check_observable);
    run_group("mut", check_mutation);
    run_group("th", check_theme);
    run_group("rt", check_router);
    run_group("frames", start_frame_checks);   // finishes the verdict from its timers

    run_group("ob", setup_observable_panel);
    run_group("mut", [] {
        g_mut_panel = new kui::RefPtr<kui::MutationObserver>(kui::MutationObserver::create(
            [](const std::vector<kui::MutationRecord>& records, kui::MutationObserver*) { on_panel_mutations(records); }));
        observe_mut_panel();
    });
    if (g_themes) show_theme();
    show_route("");

    on_click("btn-ob-inc", on_ob_inc);
    on_click("btn-ob-color", on_ob_color);
    on_click("btn-ob-unbind", on_ob_unbind);
    on_click("btn-ob-rebind", on_ob_rebind);
    on_click("btn-mut-add", on_mut_add);
    on_click("btn-mut-remove", on_mut_remove);
    on_click("btn-mut-attr", on_mut_attr);
    on_click("btn-mut-text", on_mut_text);
    on_click("btn-mut-stop", on_mut_stop);
    on_click("btn-mut-start", on_mut_start);
    on_click("btn-rs-grow", on_rs_grow);
    on_click("btn-rs-reset", on_rs_reset);
    on_click("btn-rs-stage", on_rs_stage);
    on_click("btn-io-bottom", on_io_bottom);
    on_click("btn-io-top", on_io_top);
    on_click("btn-th-light", on_th_light);
    on_click("btn-th-dark", on_th_dark);
    on_click("btn-th-list", on_th_list);
    on_click("btn-rt-home", on_rt_home);
    on_click("btn-rt-user", on_rt_user);
    on_click("btn-rt-about", on_rt_about);
    on_click("btn-rt-admin", on_rt_admin);
    on_click("btn-rt-lock", on_rt_lock);
    on_click("btn-rt-back", on_rt_back);
    on_click("btn-rt-fwd", on_rt_fwd);
}
// ---- end of examples/api_tours/data_observers/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 data binding, observers, themes & router";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_data_observers] %s\n", error.what());
        return 9;
    }
}
